# CQ BEGIN: CQ-only metadata/input transforms and UMM adapter
# These additions do not replace any native class or operator above.
# The UMM entry point remains full-sequence only; native classes retain their
# original cache path when cq_context is absent. CQ supports only before_update:
# each visual query reads only the prefix before its complete target video.
# Content always follows physical order; legacy sigma ranks are not used here.


def build_cq_masks(batch, boi_token_id=None):
    """Native causal content; same-position text and whole-video prefix queries.

    Boundaries are physical, exclusive indices. CFG drops only a visual query's
    prefix reads; it never changes content attention, convolution or state writes.
    Legacy sigma metadata is deliberately irrelevant to this Qwen3.5 path.
    """
    types = batch["token_types"]
    if types.ndim != 2 or bool(((types < 0) | (types > 3)).any()):
        raise ValueError("token_types must be [B,L] with values 0..3")
    valid = types.ne(3)
    segments = batch.get("segment_ids", torch.where(valid, 0, -1))
    if segments.shape != types.shape:
        raise ValueError("segment_ids must align with token_types")
    valid = valid & segments.ge(0)
    visual = types.eq(1) & valid
    groups = batch.get("visual_group_ids")
    if groups is None:
        previous = F.pad(visual[:, :-1], (1, 0), value=False)
        previous_segments = F.pad(segments[:, :-1], (1, 0), value=-1)
        starts = visual & (~previous | segments.ne(previous_segments))
        groups = (starts.long().cumsum(-1) - 1).masked_fill(~visual, -1)
    if groups.shape != types.shape or groups.dtype not in (torch.int32, torch.int64):
        raise ValueError("visual_group_ids must be integer [B,L]")
    if bool((groups[visual] < 0).any()):
        raise ValueError("Every visual token needs a visual_group_id")
    positions = torch.arange(types.shape[1], device=types.device)[None].expand_as(types)
    read_end = positions.clone()
    uncond = batch.get("visual_uncond_mask", batch.get("image_uncond_mask"))
    if uncond is None:
        rows = batch.get("image_uncond_rows")
        uncond = torch.zeros_like(visual) if rows is None else rows.bool()[:, None] & visual
    if uncond.shape != types.shape or bool((uncond.bool() & ~visual).any()):
        raise ValueError("CFG mask must select visual slots only")
    for row in range(types.shape[0]):
        for group in groups[row, visual[row]].unique():
            selected = torch.where(visual[row] & groups[row].eq(group))[0]
            if segments[row, selected].unique().numel() != 1:
                raise ValueError("A complete visual group must belong to one segment")
            read_end[row, selected] = selected[0]
            flags = uncond[row, selected].bool()
            if bool(flags.any()) != bool(flags.all()):
                raise ValueError("CFG dropout must select a complete visual group")
    supplied = batch.get("query_read_end")
    if supplied is not None and (supplied.shape != types.shape
            or supplied.dtype not in (torch.int32, torch.int64)
            or not torch.equal(supplied[valid], read_end[valid])):
        raise ValueError("query_read_end must use before_update physical text/video boundaries")
    same_segment = segments[:, :, None].eq(segments[:, None, :])
    same_segment &= valid[:, :, None] & valid[:, None, :]
    content = (positions[:, None, :] <= positions[:, :, None]) & same_segment
    query = (positions[:, None, :] < read_end[:, :, None]) & same_segment
    query &= ~uncond.bool()[:, :, None]
    return query, content


@dataclass
class _GDNLayout:
    """Static CQ layout: one batch row per segment, with content in physical order.

    N is the number of segments and L is their maximum length after padding.
    Scan permutations map between [all content, all query] and GDN event order.
    """

    token_indices: torch.Tensor  # [N, L], indices into the original flattened [B, T] sequence
    valid_mask: torch.Tensor  # [N, L], excludes padding added to segment rows
    scan_order: torch.Tensor  # [N, 2L], gathers [all content, all query] into scan order
    inverse_scan_order: torch.Tensor  # [N, 2L], gathers scan outputs back into the two streams
    query_conv_history: torch.Tensor  # [N, L, K-1], segment-local content indices, most recent first; -1 pads

    def pack(self, x):
        """Gather segments into independent, padded batch rows."""
        return x.flatten(0, 1)[self.token_indices] * self.valid_mask[..., None].to(x.dtype)

    def unpack(self, x, shape):
        """Restore original batch/token positions, leaving padding zero."""
        output = x.new_zeros(shape[0] * shape[1], x.shape[-1])
        return output.index_copy(0, self.token_indices[self.valid_mask], x[self.valid_mask]).view(*shape, -1)


def _gdn_layout(batch, query_allowed, content_allowed, kernel_size):
    """Translate physical-prefix visibility into one native chunk scan per layer."""
    expected_query, expected_content = build_cq_masks(batch)
    if not torch.equal(content_allowed, expected_content):
        raise ValueError("Content must retain native causal visibility")
    if not torch.equal(query_allowed, expected_query):
        raise ValueError("Query mask must exclude the entire target group (before_update)")
    types = batch["token_types"]
    valid_tokens = types.ne(3)
    segments = batch.get("segment_ids", torch.where(valid_tokens, 0, -1))
    valid_tokens = valid_tokens & segments.ge(0)
    records = []
    for row in range(types.shape[0]):
        for segment in segments[row, valid_tokens[row]].unique():
            segment_positions = torch.where(valid_tokens[row] & segments[row].eq(segment))[0]
            allowed = query_allowed[row][segment_positions[:, None], segment_positions[None, :]]
            # A query with prefix_length=r reads segment-local C[0:r], excluding C_r.
            prefix_length = allowed.long().sum(-1)
            query_conv_history = prefix_length[:, None] - torch.arange(1, kernel_size, device=types.device)
            records.append((row * types.shape[1] + segment_positions, prefix_length, query_conv_history.clamp_min(-1)))
    if not records:
        return None
    length = max(ids.numel() for ids, _, _ in records)
    token_indices = torch.stack([F.pad(ids, (0, length - ids.numel())) for ids, _, _ in records])
    valid_mask = torch.stack([torch.arange(length, device=types.device) < ids.numel() for ids, _, _ in records])
    prefix_lengths = torch.stack([F.pad(r, (0, length - r.numel()), value=length) for _, r, _ in records])
    content_positions = torch.arange(length, device=types.device)[None].expand_as(prefix_lengths)
    # At boundary r, query reads (2r) precede the content write C_r (2r+1).
    # Content writes retain physical order; stable sorting also preserves tied query order.
    # Example: prefix_lengths=[0,1,2,2] -> Q0,C0,Q1,C1,Q2,Q3,C2,C3.
    content_write_priority = 2 * content_positions + 1
    query_read_priority = 2 * prefix_lengths
    event_priority = torch.cat((content_write_priority, query_read_priority), dim=1)
    scan_order = event_priority.argsort(dim=1, stable=True)
    inverse_scan_order = scan_order.argsort(dim=1)
    query_conv_history = torch.stack([F.pad(h, (0, 0, 0, length - h.shape[0]), value=-1) for _, _, h in records])
    return _GDNLayout(
        token_indices=token_indices,
        valid_mask=valid_mask,
        scan_order=scan_order,
        inverse_scan_order=inverse_scan_order,
        query_conv_history=query_conv_history,
    )


@dataclass(frozen=True)
class _CQContext:
    """Visibility metadata only; no mutable activations or recurrent state."""

    layout: _GDNLayout | None
    query_attention_mask: torch.Tensor


@dataclass
class Qwen35CQModelOutputWithPast(Qwen3_5ModelOutputWithPast):
    query_hidden_state: torch.Tensor | None = None


def _cq_query_conv_windows(query_raw_q, content_raw_q, query_conv_history):
    """Build each query's window from visible content raw Q and its own raw Q.

    History contains segment-local content indices, most recent first; -1 pads
    with zero. Reverse it into chronological order before appending this query.
    Each window becomes a separate batch row, so queries never share a convolution.
    """
    indices = query_conv_history.flip(-1)
    rows = torch.arange(content_raw_q.shape[0], device=content_raw_q.device)[:, None, None]
    past = content_raw_q[rows, indices.clamp_min(0)].masked_fill(indices[..., None] < 0, 0)
    windows = torch.cat((past, query_raw_q[:, :, None]), dim=2)
    return windows.reshape(-1, windows.shape[2], windows.shape[3]).transpose(1, 2)


def _cq_gather(x, indices):
    """Select whole token rows with standard autograd, keeping batches disjoint.

    Scan/inverse-scan indices are permutations. Flattening batch and time avoids
    NPU gather's elementwise scatter-add backward for this row permutation.
    """
    batch, length = x.shape[:2]
    offsets = torch.arange(batch, device=x.device)[:, None] * length
    rows = (indices + offsets).reshape(-1)
    return x.flatten(0, 1).index_select(0, rows).reshape(batch, indices.shape[1], *x.shape[2:])


def _cq_validate_gdn_backend(backend):
    if backend not in ("native", "mindspeed"):
        raise ValueError(f"qwen_gdn_backend must be 'native' or 'mindspeed', got {backend!r}")
    return backend


def _cq_load_mindspeed_gdn():
    """Import the pinned public kernel lazily through the installed MindSpeed package."""
    try:
        from mindspeed.core.ssm.npu_chunk_gated_delta_rule import chunk_gated_delta_rule
    except ImportError as exc:
        raise RuntimeError(
            "qwen_gdn_backend='mindspeed' requires the locked MindSpeed and Triton-Ascend "
            "environment; run python3 scripts/setup_mindspeed.py --python, then source scripts/env_mindspeed.sh"
        ) from exc
    return chunk_gated_delta_rule


def _cq_select_chunk_gdn(backend):
    if _cq_validate_gdn_backend(backend) == "mindspeed":
        return _cq_mindspeed_chunk_gated_delta_rule
    # The HF decorator may capture another FLA callable at import time. CQ's
    # explicit native backend always uses the original Torch reference body.
    return inspect.unwrap(torch_chunk_gated_delta_rule)


def _cq_mindspeed_chunk_gated_delta_rule(
    query, key, value, *, g, beta, initial_state=None, output_final_state=False,
    use_qk_l2norm_in_kernel=True, cu_seqlens=None, **kwargs,
):
    """Map CQ's full-sequence scan to the official MindSpeed implementation.

    The caller has already projected/normalized gates and inserted read-only
    events. No sigmoid, decay transform, custom backward, or state write is added.
    Each padded segment is one batch row; query events have K=V=beta=g=0.
    """
    if any(t.device.type != "npu" for t in (query, key, value, g, beta)):
        raise ValueError("MindSpeed CQ GDN requires NPU tensors; use qwen_gdn_backend='native' on CPU")
    if any(t.dtype != torch.bfloat16 for t in (query, key, value)) or g.dtype != torch.float32:
        raise ValueError("MindSpeed CQ GDN requires BF16 Q/K/V and FP32 log-decay g")
    if initial_state is not None or output_final_state or cu_seqlens is not None:
        raise ValueError("MindSpeed CQ GDN supports uncached full-sequence batch rows only")
    if not use_qk_l2norm_in_kernel:
        raise ValueError("Qwen3.5 CQ requires native Q/K L2 normalization")
    # Transformers metadata may occur in kwargs; none is forwarded to this API.
    return _cq_load_mindspeed_gdn()(
        query, key, value, g=g, beta=beta, scale=None, initial_state=None,
        output_final_state=False, use_qk_l2norm_in_kernel=True,
        cu_seqlens=None, chunk_size=64, head_first=False,
    )


def resolve_gdn_backend_identity(backend):
    """Return the actual computation provider for logging and strict resume checks."""
    import hashlib
    import importlib.metadata
    from pathlib import Path

    backend = _cq_validate_gdn_backend(backend)
    kernel = (_cq_load_mindspeed_gdn() if backend == "mindspeed"
              else inspect.unwrap(torch_chunk_gated_delta_rule))
    implementation = inspect.unwrap(kernel)
    expected_module = ("mindspeed.core.ssm.npu_chunk_gated_delta_rule"
                       if backend == "mindspeed" else __name__)
    expected_name = "chunk_gated_delta_rule" if backend == "mindspeed" else "torch_chunk_gated_delta_rule"
    if implementation.__module__ != expected_module or implementation.__name__ != expected_name:
        raise RuntimeError(f"Unexpected {backend} GDN provider: {implementation!r}")
    source = Path(inspect.getsourcefile(implementation)).resolve()
    if backend == "mindspeed":
        import importlib
        module = importlib.import_module(expected_module)
        if source != Path(module.__file__).resolve():
            raise RuntimeError("MindSpeed GDN callable no longer resolves to its official source module")
        try:
            triton_version = importlib.metadata.version("triton-ascend")
        except importlib.metadata.PackageNotFoundError as exc:
            raise RuntimeError("MindSpeed CQ GDN requires an installed Triton-Ascend distribution") from exc
    else:
        triton_version = None
    return {
        "backend": backend, "provider": "MindSpeed" if backend == "mindspeed" else "Qwen3.5 Torch reference",
        "module": implementation.__module__, "function": implementation.__name__,
        "file": str(source), "source_sha256": hashlib.sha256(source.read_bytes()).hexdigest(),
        "triton_version": triton_version, "cq_index_implementation": "batched_row_index_select_v1",
    }


def _cq_interleave_readonly_queries(content_q, query_q, key, value, g, beta, scan_order):
    """Interleave query reads with unchanged content write inputs for the native GDN.

    Query events use their own Q with K=V=0, beta=0 and g=0. Since g is log
    decay, exp(g)=1: a query reads the current state without changing it.
    """
    q = _cq_gather(torch.cat((content_q, query_q), dim=1), scan_order)
    state_inputs = tuple(_cq_gather(torch.cat((x, torch.zeros_like(x)), dim=1), scan_order)
                         for x in (key, value, g, beta))
    return (q, *state_inputs)


def _cq_attention_mask(allowed, dtype):
    valid = allowed.any(-1, keepdim=True)
    safe = allowed.clone()
    safe[..., 0] |= ~valid.squeeze(-1)
    additive_mask = torch.zeros_like(safe[:, None], dtype=dtype)
    additive_mask.masked_fill_(~safe[:, None], torch.finfo(dtype).min)
    return additive_mask, valid



class Qwen35CQBackbone(Qwen3_5TextModel):
    """UMM CQ entry point with native Qwen3.5 text-model weights.

    Both streams stay aligned with input positions. UMM supervises query_hidden
    at those same positions (no label shift) and selects whole visual groups as
    generator conditions. Generation also uses query_stream=True; masked content
    states are not a substitute for before_update query states.
    """

    config_class = Qwen3_5TextConfig
    _no_split_modules = ["Qwen3_5DecoderLayer"]
    _keys_to_ignore_on_load_unexpected = [r"^mtp\.", r"^(model\.)?visual\.", r"^lm_head\."]
    _supports_flash_attn = False  # Full attention requires explicit CQ masks.
    _can_compile_fullgraph = False  # Segment/group metadata is prepared in Python.

    def __init__(self, config, *, mask_token_id=None, image_mask_token_id=None, mask_query_read=None):
        config = deepcopy(getattr(config, "text_config", config))
        for name, value in (("mask_token_id", mask_token_id), ("image_mask_token_id", image_mask_token_id),
                            ("mask_query_read", mask_query_read)):
            if value is not None:
                setattr(config, name, value)
        mode = getattr(config, "mask_query_read", "before_update")
        if mode != "before_update":
            raise ValueError("CQ requires mask_query_read='before_update' to exclude the whole target group")
        config.mask_query_read = mode
        config.image_input_noise_strength = getattr(config, "image_input_noise_strength", 0.0)
        config.boi_token_id = getattr(config, "boi_token_id", None)
        config.mask_token_id = getattr(config, "mask_token_id", None)
        config.image_mask_token_id = getattr(config, "image_mask_token_id", config.mask_token_id)
        if config.linear_num_value_heads % config.linear_num_key_heads:
            raise ValueError("GDN value head count must be divisible by key head count")
        super().__init__(config)
        self.gradient_checkpointing = bool(getattr(config, "gradient_checkpointing", False))
        self.configure_gdn_backend(getattr(config, "qwen_gdn_backend", "native"))

    def configure_gdn_backend(self, backend):
        """Set a serialized, explicit CQ scan backend without changing model weights."""
        backend = _cq_validate_gdn_backend(backend)
        self.config.qwen_gdn_backend = backend
        for module in self.modules():
            if isinstance(module, Qwen3_5GatedDeltaNet):
                module.qwen_gdn_backend = backend

    def gdn_backend_identity(self):
        """Audit every GDN layer before returning the actual provider identity."""
        backend = self.config.qwen_gdn_backend
        for module in self.modules():
            if isinstance(module, Qwen3_5GatedDeltaNet) and module.qwen_gdn_backend != backend:
                raise RuntimeError("CQ GDN layer backend disagrees with backbone config")
        return resolve_gdn_backend_identity(backend)

    @classmethod
    def from_pretrained(cls, pretrained_model_name_or_path, *model_args, **kwargs):
        """Load native text or multimodal weights without silently missing the backbone."""
        return_info = kwargs.pop("output_loading_info", False)
        kwargs.setdefault("key_mapping", {
            r"^model\.language_model\.": "",
            r"^language_model\.": "",
            r"^model\.": "",
        })
        model, info = super().from_pretrained(
            pretrained_model_name_or_path, *model_args, output_loading_info=True, **kwargs)
        missing = info["missing_keys"]
        if missing or info["unexpected_keys"] or info["mismatched_keys"] or info["error_msgs"]:
            raise ValueError(f"Incompatible Qwen3.5 backbone weights: {info}")
        return (model, info) if return_info else model

    def embed_content(self, batch):
        content = batch.get("inputs_embeds")
        if content is not None:
            if content.shape != (*batch["input_ids"].shape, self.config.hidden_size):
                raise ValueError("inputs_embeds must have shape [B,L,hidden_size]")
            return content
        if not bool(batch["token_types"].eq(1).any()):
            return self.embed_tokens(batch["input_ids"])
        raise ValueError("Visual slots require native visual inputs_embeds; image latents are not Qwen vision features")

    def _video_layout(self, batch):
        ids = batch["input_ids"]
        if ids.ndim != 2 or ids.shape[1] == 0 or ids.dtype not in (torch.int32, torch.int64):
            raise ValueError("input_ids must be a nonempty integer [B,L] tensor")
        valid = batch.get("attention_mask", torch.ones_like(ids, dtype=torch.bool)).bool()
        if valid.shape != ids.shape:
            raise ValueError("attention_mask must align with input_ids")
        segments = batch.get("segment_ids", torch.where(valid, 0, -1))
        if segments.shape != ids.shape:
            raise ValueError("segment_ids must align with input_ids")
        valid = valid & segments.ge(0)
        segments = segments.masked_fill(~valid, -1)
        cfg = self.vision_encoder.config
        video = ids.eq(cfg.video_token_id) & valid
        mm_types = batch.get("mm_token_type_ids", video.long() * 2)
        if (mm_types.shape != ids.shape or not torch.equal(mm_types.eq(2) & valid, video)
                or bool(((mm_types != 0) & (mm_types != 2) & valid).any())
                or bool((ids.eq(cfg.image_token_id) & valid).any())):
            raise ValueError("This video entry expects native text/video mm_token_type_ids (0/2)")
        types = torch.zeros_like(ids)
        types[ids.eq(cfg.vision_start_token_id) | ids.eq(cfg.vision_end_token_id)] = 2
        types[video], types[~valid] = 1, 3
        if "token_types" in batch and not torch.equal(batch["token_types"], types):
            raise ValueError("CQ token_types differ from native video slots/padding; do not use mm_token_type_ids")
        grids = batch.get("video_grid_thw", ids.new_empty((0, 3))).to(ids.device)
        counts = self.vision_encoder.token_counts(grids).tolist()
        groups = torch.full_like(ids, -1)
        rows, indices = [], []
        video_id = 0
        merge = self.vision_encoder.visual.spatial_merge_size
        for row in range(ids.shape[0]):
            slots = torch.where(video[row])[0]
            offset = 0
            while offset < slots.numel():
                if video_id >= len(counts) or offset + counts[video_id] > slots.numel():
                    raise ValueError("Native video placeholder count does not match video_grid_thw")
                selected = slots[offset:offset + counts[video_id]]
                t, h, w = grids[video_id].tolist()
                frames = selected.view(t, h * w // merge**2)
                if (not bool((frames[:, 1:] - frames[:, :-1]).eq(1).all())
                        or bool((frames[:, 0] < 1).any()) or bool((frames[:, -1] + 1 >= ids.shape[1]).any())):
                    raise ValueError("Each native video frame must have contiguous visual placeholders")
                if (not bool(ids[row, frames[:, 0] - 1].eq(cfg.vision_start_token_id).all())
                        or not bool(ids[row, frames[:, -1] + 1].eq(cfg.vision_end_token_id).all())):
                    raise ValueError("Each video frame requires native vision_start/vision_end markers")
                start, end = int(selected[0]) - 1, int(selected[-1]) + 2
                if not bool(valid[row, start:end].all()) or segments[row, start:end].unique().numel() != 1:
                    raise ValueError("A complete video must remain inside one valid packed segment")
                groups[row, selected] = video_id
                rows.append(row)
                indices.append(selected)
                offset += counts[video_id]
                video_id += 1
        if video_id != len(counts):
            raise ValueError("Native video placeholder count does not match video_grid_thw")
        rows = ids.new_tensor(rows)
        for key, expected in (("visual_group_ids", groups), ("video_batch_indices", rows)):
            if key in batch and not torch.equal(batch[key], expected):
                raise ValueError(f"{key} does not match processor video order")
        if "video_token_indices" in batch:
            supplied = batch["video_token_indices"]
            if (not isinstance(supplied, (list, tuple)) or len(supplied) != len(indices)
                    or any(not torch.equal(a, b) for a, b in zip(supplied, indices))):
                raise ValueError("video_token_indices do not match native video placeholders")

        positions = ids.new_zeros((3, *ids.shape))
        read_end = torch.arange(ids.shape[1], device=ids.device)[None].expand_as(ids).clone()
        for row, slots in zip(rows.tolist(), indices):
            read_end[row, slots] = slots[0]
        for row in range(ids.shape[0]):
            for segment in segments[row, valid[row]].unique():
                selected = torch.where(valid[row] & segments[row].eq(segment))[0]
                local_videos = [i for i, r in enumerate(rows.tolist())
                                if r == row and segments[row, indices[i][0]] == segment]
                native_positions, _ = self.vision_encoder.get_rope_index(
                    ids[row:row + 1, selected], mm_types[row:row + 1, selected],
                    video_grid_thw=grids[local_videos] if local_videos else None,
                )
                positions[:, row, selected] = native_positions[:, 0]
        if "query_read_end" in batch and not torch.equal(batch["query_read_end"], read_end):
            raise ValueError("query_read_end must use the physical video prefix/text position")
        if "position_ids" in batch and not torch.equal(batch["position_ids"], positions):
            raise ValueError("position_ids must match native Qwen M-RoPE for each segment")
        return dict(input_ids=ids, token_types=types, segment_ids=segments, query_read_end=read_end,
                    position_ids=positions, visual_group_ids=groups, video_grid_thw=grids,
                    video_batch_indices=rows, video_token_indices=tuple(indices))

    @staticmethod
    def _video_flags(batch, name, count, device, default):
        flags = batch.get(name, torch.full((count,), default, device=device, dtype=torch.bool))
        if not isinstance(flags, torch.Tensor) or flags.shape != (count,) or flags.dtype != torch.bool:
            raise ValueError(f"{name} must be boolean [videos]")
        return flags.to(device)

    def prepare_inputs(self, batch):
        """Return aligned CQ embeddings/metadata without modifying the caller's batch."""
        prepared = self._video_layout(batch)
        ids, grids = prepared["input_ids"], prepared["video_grid_thw"]
        rows, indices = prepared["video_batch_indices"], prepared["video_token_indices"]
        count = len(indices)
        observed = self._video_flags(batch, "video_observed_mask", count, ids.device, True)
        uncond = self._video_flags(batch, "video_uncond_mask", count, ids.device, False)
        if any(key in batch for key in ("image_uncond_mask", "image_uncond_rows", "visual_uncond_mask")):
            raise ValueError("UMMVideo CFG uses video_uncond_mask, one flag per complete video")
        content = self.embed_tokens(ids.masked_fill(prepared["token_types"].eq(1),
                                                           self.config.image_mask_token_id))
        features = batch.get("video_features")
        pixels = batch.get("pixel_values_videos")
        if "pixel_video_ids" in batch:
            raise ValueError("pixel_video_ids is unsupported; use one Qwen representation per batch")
        if features is not None and pixels is not None:
            raise ValueError("Supply video_features or pixel_values_videos for the whole batch, not both")
        if features is not None:
            if not isinstance(features, (list, tuple)) or len(features) != count:
                raise ValueError("video_features must contain one post-merger tensor/None per video")
            features = list(features)
        else:
            features = [None] * count
            # CQ input adapter: online pixels follow observed videos in processor order.
            if pixels is not None:
                encoded = self.vision_encoder(pixels, grids[observed])
                for index, values in zip(torch.where(observed)[0].tolist(), encoded):
                    features[index] = values
        mask = torch.zeros_like(ids, dtype=torch.bool)
        for i, (row, slots) in enumerate(zip(rows.tolist(), indices)):
            values = features[i]
            if observed[i]:
                if (not isinstance(values, torch.Tensor) or values.shape != (slots.numel(), content.shape[-1])
                        or not values.is_floating_point() or values.device != content.device):
                    raise ValueError("Observed video features must match native token count, width and device")
                content[row, slots] = values.to(content.dtype)
            elif values is not None:
                raise ValueError("Unobserved target videos must not supply visual features")
            mask[row, slots] = uncond[i]
        targets = batch.get("target_video_ids", torch.arange(count, device=ids.device))
        if (not isinstance(targets, torch.Tensor) or targets.ndim != 1 or targets.dtype not in (torch.int32, torch.int64)
                or targets.unique().numel() != targets.numel() or bool(((targets < 0) | (targets >= count)).any())):
            raise ValueError("target_video_ids must be unique indices into processor-order videos")
        prepared.update(inputs_embeds=content, visual_uncond_mask=mask, target_video_ids=targets.to(ids.device))
        return prepared

    def _positions(self, batch, positions):
        types = batch["token_types"]
        positions = batch.get("position_ids") if positions is None else positions
        if positions is None:
            positions = torch.zeros((3, *types.shape), device=types.device, dtype=torch.long)
            valid = types.ne(3)
            segments = batch.get("segment_ids", torch.where(valid, 0, -1))
            for row in range(types.shape[0]):
                for segment in segments[row, valid[row] & segments[row].ge(0)].unique():
                    indices = torch.where(valid[row] & segments[row].eq(segment))[0]
                    local = types[row, indices][None]
                    if bool(local.eq(1).any()):
                        raise ValueError("Visual input requires native position_ids from the multimodal backbone")
                    else:
                        local_positions = torch.arange(indices.numel(), device=types.device)[None, None].expand(3, 1, -1)
                    positions[:, row, indices] = local_positions[:, 0]
            return positions
        positions = positions.to(device=types.device)
        if positions.shape == types.shape:
            return positions[None].expand(3, -1, -1)
        if positions.ndim != 3 or positions.shape[1:] != types.shape or positions.shape[0] not in {2, 3, 4}:
            raise ValueError("position_ids must be [B,L], [2,B,L], [3,B,L] or native [4,B,L]")
        if positions.shape[0] == 4:
            return positions[1:]
        if positions.shape[0] == 2:
            # Legacy UMM images have H/W axes. Their T coordinate stays at the
            # image anchor; text uses the same scalar coordinate on all axes.
            image = types.eq(1)
            starts = image & ~F.pad(image[:, :-1], (1, 0), value=False)
            indices = torch.arange(types.shape[1], device=types.device)[None].expand_as(types)
            anchors = torch.where(starts, indices, 0).cummax(-1).values
            temporal = torch.where(image, positions[0].gather(1, anchors), positions[0])
            return torch.cat((temporal[None], positions), dim=0)
        return positions

    def forward(self, batch, *, return_content=False, cache=None, cache_mode=None,
                positions=None, masks=None, query_stream=True):
        if self.config.mask_query_read != "before_update":
            raise ValueError("CQ requires mask_query_read='before_update' to exclude the whole target group")
        if cache is not None or cache_mode is not None:
            raise NotImplementedError("Qwen35CQBackbone currently supports full-sequence execution only")
        ids = batch["input_ids"]
        if ids.ndim != 2 or ids.shape[1] == 0:
            raise ValueError("input_ids must be a nonempty [B,L] tensor")
        batch = {**batch, "token_types": batch.get("token_types", torch.zeros_like(ids))}
        types = batch["token_types"]
        if types.shape != ids.shape:
            raise ValueError("token_types must align with input_ids")
        content = self.embed_content(batch)
        query = None
        if query_stream:
            for name in ("mask_token_id", "image_mask_token_id"):
                token = getattr(self.config, name)
                if token is None or not 0 <= token < self.config.vocab_size:
                    raise ValueError(f"Set a valid {name} before enabling the query stream")
            mask_ids = torch.full_like(ids, self.config.mask_token_id)
            query = self.embed_tokens(mask_ids.masked_fill(types.eq(1), self.config.image_mask_token_id))
        query_allowed, content_allowed = build_cq_masks(batch, self.config.boi_token_id)
        if masks is not None:
            requested_query, requested_content = masks
            if (requested_query.dtype != torch.bool or requested_content.dtype != torch.bool
                    or not torch.equal(requested_query, query_allowed)
                    or not torch.equal(requested_content, content_allowed)):
                raise ValueError("Explicit masks must match physical before_update/segment/CFG visibility")
        layout = _gdn_layout(batch, query_allowed, content_allowed, self.config.linear_conv_kernel_dim)
        # Use the native decoder checkpoint wrapper. Non-reentrant checkpoint
        # keeps gradients through query tensors supplied as keyword arguments.
        for layer in self.layers:
            layer.gradient_checkpointing = self.gradient_checkpointing
            if self.gradient_checkpointing:
                layer._gradient_checkpointing_func = partial(checkpoint, use_reentrant=False)
        outputs = super().forward(
            inputs_embeds=content,
            position_ids=self._positions(batch, positions),
            attention_mask={"full_attention": content_allowed, "linear_attention": None},
            use_cache=False,
            cq_context=_CQContext(layout, query_allowed),
            query_hidden_states=query,
        )
        valid = types.ne(3)
        if "segment_ids" in batch:
            valid = valid & batch["segment_ids"].ge(0)
        output = {"query_hidden": None if query is None else outputs.query_hidden_state * valid[..., None]}
        if return_content or not query_stream:
            output["content_hidden"] = outputs.last_hidden_state * valid[..., None]
        return output


class _VisionWeights(Qwen3_5VisionModel):
    # Loading the vision part of a full conditional-generation checkpoint is
    # deliberate. Missing vision tensors are still checked strictly below.
    _keys_to_ignore_on_load_unexpected = [r"^(model\.)?language_model\.", r"^lm_head\.", r"^mtp\."]


class Qwen35VideoEncoder(nn.Module):
    # These native methods only need config.vision_config and each other; reuse
    # them verbatim rather than reconstructing the multimodal position rules.
    get_vision_position_ids = Qwen3_5Model.get_vision_position_ids
    get_rope_index = Qwen3_5Model.get_rope_index

    def __init__(self, config, *, visual=None):
        super().__init__()
        self.config = deepcopy(config)
        self.visual = Qwen3_5VisionModel(self.config.vision_config) if visual is None else visual
        if self.visual.config.out_hidden_size != self.config.text_config.hidden_size:
            raise ValueError("Qwen visual merger output must match the language hidden size")

    @classmethod
    def from_pretrained(cls, path, *, config=None, attn_implementation="sdpa", **kwargs):
        config = deepcopy(config) if config is not None else Qwen3_5Config.from_pretrained(path, local_files_only=True)
        kwargs.setdefault("local_files_only", True)
        visual, info = _VisionWeights.from_pretrained(
            path, config=config.vision_config, attn_implementation=attn_implementation,
            key_mapping={r"^model\.visual\.": "", r"^visual\.": ""},
            output_loading_info=True, **kwargs,
        )
        errors = {key: info[key] for key in ("missing_keys", "unexpected_keys", "mismatched_keys", "error_msgs")
                  if info[key]}
        if errors:
            raise ValueError(f"Incompatible Qwen3.5 vision weights: {errors}")
        return cls(config, visual=visual).eval()

    def token_counts(self, grid_thw):
        if (not isinstance(grid_thw, torch.Tensor) or grid_thw.ndim != 2 or grid_thw.shape[1] != 3
                or grid_thw.dtype not in (torch.int32, torch.int64)):
            raise ValueError("video_grid_thw must be an integer [videos,3] tensor")
        merge = self.visual.spatial_merge_size
        if bool((grid_thw <= 0).any()) or bool((grid_thw[:, 1:] % merge != 0).any()):
            raise ValueError("Video grids must be positive with H/W divisible by spatial_merge_size")
        return grid_thw.prod(-1) // merge**2

    def forward(self, pixel_values_videos, video_grid_thw):
        counts = self.token_counts(video_grid_thw)
        cfg = self.visual.config
        width = cfg.in_channels * cfg.temporal_patch_size * cfg.patch_size**2
        shape = (int(video_grid_thw.prod(-1).sum()), width)
        if (not isinstance(pixel_values_videos, torch.Tensor) or pixel_values_videos.shape != shape
                or not pixel_values_videos.is_floating_point()):
            raise ValueError(f"pixel_values_videos must contain native flattened patches with shape {shape}")
        if pixel_values_videos.device != self.visual.device:
            raise ValueError("Video patches and the Qwen visual encoder must be on the same device")
        if not counts.numel():
            return ()
        output = self.visual(pixel_values_videos.to(self.visual.dtype), grid_thw=video_grid_thw, return_dict=True)
        return output.pooler_output.split(counts.tolist())


__all__ += ["Qwen35CQBackbone", "Qwen35VideoEncoder", "build_cq_masks"]
# CQ END
